function reconstruirResumo(indice) {
  if (!indice) return "";

  const palavras = [];

  for (const [palavra, posicoes] of Object.entries(indice)) {
    for (const posicao of posicoes) {
      palavras[posicao] = palavra;
    }
  }

  return palavras.filter(Boolean).join(" ");
}

function limpar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

const configuracoes = $("Definir assuntos").all();
const respostas = $input.all();
const saida = [];

for (let i = 0; i < respostas.length; i++) {
  const configuracao = configuracoes[i]?.json || {};
  const resposta = respostas[i]?.json || {};

  // Ignora uma eventual resposta de erro da API.
  if (resposta.error) {
    continue;
  }

  const resultados = resposta.results || [];

  for (const artigo of resultados) {
    const autores = (artigo.authorships || [])
      .map(item => item.author?.display_name)
      .filter(Boolean)
      .slice(0, 6);

    const resumo = reconstruirResumo(
      artigo.abstract_inverted_index
    );

    const link =
      artigo.doi ||
      artigo.best_oa_location?.landing_page_url ||
      artigo.primary_location?.landing_page_url ||
      artigo.id;

    const identificador = artigo.doi || artigo.id;

    saida.push({
      json: {
        chave: `${configuracao.categoria}|${identificador}`,

        id: identificador,
        categoria: configuracao.categoria,
        quantidade: configuracao.quantidade,
        dataInicial: configuracao.dataInicial,
        dataFinal: configuracao.dataFinal,

        titulo:
          limpar(artigo.display_name) ||
          "Sem título",

        autores: autores.join(", "),

        data: artigo.publication_date,

        revista:
          artigo.primary_location?.source?.display_name ||
          "Periódico não informado",

        assunto:
          artigo.primary_topic?.display_name || "",

        resumo:
          limpar(resumo).slice(0, 700),

        link,

        doi: artigo.doi || "",

        acessoAberto:
          artigo.open_access?.is_oa === true,

        citacoes:
          artigo.cited_by_count || 0,

        relevancia:
          artigo.relevance_score || 0
      }
    });
  }
}

return saida;

function escapar(texto) {
  const mapa = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  };

  return String(texto || "").replace(
    /[&<>"']/g,
    caractere => mapa[caractere]
  );
}

function formatarData(data) {
  if (!data) return "Data não informada";

  return new Intl.DateTimeFormat("pt-BR").format(
    new Date(`${data}T12:00:00Z`)
  );
}

const artigos = $input.all().map(item => item.json);
const grupos = {};

for (const artigo of artigos) {
  if (!grupos[artigo.categoria]) {
    grupos[artigo.categoria] = [];
  }

  grupos[artigo.categoria].push(artigo);
}

let html = `
<div style="font-family:Arial,sans-serif;max-width:850px;margin:auto;color:#222">
  <h1 style="color:#174ea6">Radar acadêmico semanal</h1>
  <p>
    Artigos publicados entre
    <strong>${formatarData(artigos[0]?.dataInicial)}</strong> e
    <strong>${formatarData(artigos[0]?.dataFinal)}</strong>.
  </p>
`;

for (const [categoria, lista] of Object.entries(grupos)) {
  const quantidade = Number(lista[0]?.quantidade || 5);

  const selecionados = lista
    .sort((a, b) =>
      (b.relevancia - a.relevancia) ||
      (b.citacoes - a.citacoes) ||
      String(b.data).localeCompare(String(a.data))
    )
    .slice(0, quantidade);

  html += `
    <h2 style="margin-top:32px;border-bottom:2px solid #174ea6">
      ${escapar(categoria)}
    </h2>
  `;

  for (const artigo of selecionados) {
    html += `
      <div style="padding:12px 0;border-bottom:1px solid #ddd">
        <h3 style="margin-bottom:6px">
          <a href="${escapar(artigo.link)}">
            ${escapar(artigo.titulo)}
          </a>
        </h3>

        <p style="margin:4px 0">
          <strong>Autores:</strong>
          ${escapar(artigo.autores || "Não informados")}
        </p>

        <p style="margin:4px 0">
          <strong>Periódico:</strong> ${escapar(artigo.revista)} |
          <strong>Publicação:</strong> ${formatarData(artigo.data)}
          ${artigo.acessoAberto ? " | 🟢 Acesso aberto" : ""}
        </p>

        ${
          artigo.assunto
            ? `<p><strong>Assunto:</strong> ${escapar(artigo.assunto)}</p>`
            : ""
        }

        <p>${escapar(artigo.resumo || "Resumo não disponibilizado.")}</p>
      </div>
    `;
  }
}

html += `
  <p style="margin-top:32px;color:#666;font-size:12px">
    Relatório automático gerado pelo n8n com dados do OpenAlex.
  </p>
</div>
`;

return [{
  json: {
    subject: `Radar acadêmico semanal – ${formatarData(
      artigos[0]?.dataFinal
    )}`,
    html
  }
}];
